from pathlib import Path; folders=[Path('src/pages/jogos'), Path('src/jogos')]; fixed=0
for folder in folders:
    if not folder.exists():
        continue
    for path in folder.rglob('*.astro'):
        text = path.read_text(encoding='utf-8', errors='ignore')
        original = text
        if any(token in text for token in ['Ã','Â','â€','â†']):
            try:
                recoded = text.encode('latin1').decode('utf-8')
                if recoded.count('Ã') + recoded.count('Â') + recoded.count('â€') <= text.count('Ã') + text.count('Â') + text.count('â€'):
                    text = recoded
            except Exception:
                pass
        cleanup = {'Â ': ' ', 'Â': ''}
        for bad, good in cleanup.items():
            text = text.replace(bad, good)
        if text != original:
            path.write_text(text, encoding='utf-8')
            fixed += 1
print(f'fixed_files={fixed}')
